###############################################################################
## Process all scenario simulation outputs
###############################################################################
##
## PURPOSE
##
## This script processes trajectories generated by Simulate_all_scenarios.R
## into a single analysis-ready data frame.
##
## It processes:
##
## 1. Original scenario analyses:
##      - three baseline transmission settings
##      - annual and biannual treatment
##      - ivermectin and moxidectin
##      - variable-response (VR) and GR-only models
##
## 2. Revised sensitivity analyses at approximately 70% baseline prevalence:
##      - ivermectin MDA
##      - annual and biannual treatment
##      - VR and GR-only models
##      - primary calibration
##      - moderate SOR-increase calibration
##      - weak SOR-increase calibration
##      - no offspring-phenotype selection
##      - wider-prevalence calibration
##
## Each input .Rdata file is expected to contain an object called OutputM.
##
## Missing files are reported and skipped rather than stopping the script.
##
## OUTPUT
##
## processed_all_scenarios.RData
##     processed_all       processed trajectory-level results
##     scenario_manifest   description of scenario files
##
## processed_all_scenarios.csv
##     CSV version of processed_all
##
###############################################################################


library(dplyr)


###############################################################################
## Paths
###############################################################################

output_dir <- "output"

source("../Fitting/equations.R")

###############################################################################
## Names of model outcomes extracted from each trajectory
###############################################################################

outcome_columns <- c(
  "Final_SOR_proportion_worms",
  "Final_SOR_proportion_mf",
  "Final_Prevalence_GR",
  "Final_Prevalence_SOR",
  "Final_Prevalence",
  "ABR",
  "MDA_frequency",
  "SOR_present",
  "Initial_SOR_proportion_worms",
  "MDAi",
  "Final_SOR_proportion_worms20yr",
  "pOTTIS"
)

###############################################################################
## Function to calculate summary outcomes from one trajectory
###############################################################################

calculate_final_data <- function(
    yout,
    ABR,
    MDAf,
    SORpresent,
    MDAi,
    my_k0,
    my_k1) {
  
  ## -------------------------------------------------------------------------
  ## SOR proportions and mf prevalence through time
  ## -------------------------------------------------------------------------
  
  worm_denominator <-
    yout[, 3] +
    yout[, 4] +
    yout[, 7] +
    yout[, 8]
  
  mf_denominator <-
    yout[, 5] +
    yout[, 9]
  
  RecSOR_proportion_worms <- ifelse(
    worm_denominator > 0,
    1 -
      (yout[, 3] + yout[, 4]) /
      worm_denominator,
    0
  )
  
  RecSOR_proportion_mf <- ifelse(
    mf_denominator > 0,
    1 -
      yout[, 5] /
      mf_denominator,
    0
  )
  
  RecPrevalenceGR <-
    prevalence(
      yout[, 5],
      my_k0,
      my_k1
    )
  
  RecPrevalenceSOR <-
    prevalence(
      yout[, 9],
      my_k0,
      my_k1
    )
  
  RecPrevalence <-
    prevalence(
      yout[, 9] + yout[, 5],
      my_k0,
      my_k1
    )
  
  ## -------------------------------------------------------------------------
  ## Outcomes used for annual/biannual comparison
  ##
  ## Annual:
  ##     20 annual rounds -> evaluate at end of 20 years
  ##
  ## Biannual:
  ##     40 biannual rounds -> evaluate at year 10 for the comparison
  ##     after 20 treatment rounds.
  ##
  ##     The SOR proportion at the end of the complete 20-year biannual
  ##     simulation is additionally retained separately.
  ## -------------------------------------------------------------------------
  
  if (MDAf == 0.5) {
    
    ## Find time point closest to 10 years.
    ## This is robust to trajectory thinning.
    time10 <- which.min(
      abs(yout[, 1] - 10)
    )
    
    RecFinal_SOR_proportion_worms <- RecSOR_proportion_worms[time10]
    
    RecFinal_SOR_proportion_worms20 <- tail(RecSOR_proportion_worms,1)
    
    RecFinal_SOR_proportion_mf <- RecSOR_proportion_mf[time10]
    
    RecFinalPrevalence <- RecPrevalence[time10]
    
    RecFinalPrevalenceGR <- RecPrevalenceGR[time10]
    
    RecFinalPrevalenceSOR <- RecPrevalenceSOR[time10]
    
    
  } else {
    
    RecFinal_SOR_proportion_worms <- tail(RecSOR_proportion_worms, 1)
    
    RecFinal_SOR_proportion_worms20 <- RecFinal_SOR_proportion_worms
    
    RecFinal_SOR_proportion_mf <- tail(RecSOR_proportion_mf, 1)
    
    RecFinalPrevalence <-tail(RecPrevalence,1)
    
    RecFinalPrevalenceGR <-tail(RecPrevalenceGR,1)
    
    RecFinalPrevalenceSOR <-tail(RecPrevalenceSOR,1)
  }
  
  
  ## -------------------------------------------------------------------------
  ## Initial SOR worm proportion
  ## Identify the trajectory point closest to time zero. 
  ## -------------------------------------------------------------------------
  
  initial_index <- which.min(
    abs(yout[, 1])
  )
  
  RecInitial_SOR_proportion_worms <- RecSOR_proportion_worms[initial_index]
  
  ## -------------------------------------------------------------------------
  ## Time to pOTTIS
  ##
  ## Evaluate prevalence at treatment-round observation times and identify
  ## the first time mf prevalence falls below 1.4%.
  ##
  ## If pOTTIS is not reached during the simulation, return NA.
  ## -------------------------------------------------------------------------
  
  if (MDAf == 0.5) {
    
    obs_times <- seq(
      from = 0,
      to = 40 * MDAf,
      by = MDAf
    )
    
  } else {
    
    obs_times <- seq(
      from = 0,
      to = 20 * MDAf,
      by = MDAf
    )
  }
  
  ## Find the stored trajectory point closest to each observation time.
  ## This also works when saved trajectories have been thinned.
  
  obs_ind <- vapply(
    obs_times,
    function(t) {
      
      which.min(
        abs(yout[, 1] - t)
      )
      
    },
    integer(1)
  )
  
  obs <- RecPrevalence[obs_ind]
  
  below_pOTTIS <- which(
    obs < 0.014
  )
  
  if (length(below_pOTTIS) == 0) {
    
    pOTTIS <- NA_real_
    
  } else {
    
    pOTTIS <-
      obs_times[
        min(below_pOTTIS)
      ]
  }
  
  ## -------------------------------------------------------------------------
  ## Return outcomes
  ## -------------------------------------------------------------------------
  
  c(
    RecFinal_SOR_proportion_worms,
    RecFinal_SOR_proportion_mf,
    RecFinalPrevalenceGR,
    RecFinalPrevalenceSOR,
    RecFinalPrevalence,
    ABR,
    MDAf,
    SORpresent,
    RecInitial_SOR_proportion_worms,
    MDAi,
    RecFinal_SOR_proportion_worms20,
    pOTTIS
  )
}

###############################################################################
## Function to process one scenario file
###############################################################################

process_scenario_file <- function(
    filename,
    scenario_group,
    calibration,
    model,
    drug,
    frequency,
    ABR) {
  
  
  ## -------------------------------------------------------------------------
  ## Check file
  ## -------------------------------------------------------------------------
  
  if (!file.exists(filename)) {
    
    warning(
      "Skipping missing file: ",
      filename
    )
    
    return(NULL)
  }
  
  message(
    "Processing: ",
    scenario_group,
    " | ",
    calibration,
    " | ",
    model,
    " | ",
    drug,
    " | ",
    frequency,
    " | ABR = ",
    ABR
  )
  
  ## -------------------------------------------------------------------------
  ## Load OutputM into an isolated environment
  ##
  ## This prevents load() from overwriting objects already in the workspace.
  ## -------------------------------------------------------------------------
  
  e <- new.env()
  
  load(
    filename,
    envir = e
  )
  
  if (!exists(
    "OutputM",
    envir = e,
    inherits = FALSE
  )) {
    
    warning(
      "OutputM not found in: ",
      filename
    )
    
    return(NULL)
  }
  
  
  OutputM_local <- e$OutputM
  
  ## -------------------------------------------------------------------------
  ## Scenario settings
  ## -------------------------------------------------------------------------
  
  MDAf <- ifelse(
    frequency == "Biannual",
    0.5,
    1
  )
  
  MDAi <- ifelse(
    drug == "Ivermectin",
    1,
    0
  )
  
  SORpresent <- ifelse(
    model == "VR",
    1,
    0
  )
  
  ## fixed-parameters.R uses ABR and MDAi
  source(
    "../Fitting/fixed-parameters.R",
    local = TRUE
  )
  
  ## -------------------------------------------------------------------------
  ## Process trajectories
  ## -------------------------------------------------------------------------
  
  RecFinal <- matrix(
    NA_real_,
    nrow = length(OutputM_local),
    ncol = length(outcome_columns)
  )
  
  for (n in seq_along(OutputM_local)) {
    
    yout <- OutputM_local[[n]]
    
    RecFinal[n, ] <-
      calculate_final_data(
        yout = yout,
        ABR = ABR,
        MDAf = MDAf,
        SORpresent = SORpresent,
        MDAi = MDAi,
        my_k0 = my_k0,
        my_k1 = my_k1
      )
  }
  
  ## -------------------------------------------------------------------------
  ## Convert to data frame and add scenario identifiers
  ## -------------------------------------------------------------------------
  
  out <- as.data.frame(
    RecFinal
  )
  
  names(out) <- outcome_columns
  
  out$Scenario_group <-
    scenario_group
  
  out$Calibration <-
    calibration
  
  out$Model <-
    model
  
  out$Drug <-
    drug
  
  out$Treatment_frequency <-
    frequency
  
  out$Sample <-
    seq_len(
      nrow(out)
    )
  
  out$Source_file <-
    basename(filename)
  
  out
}


###############################################################################
## ORIGINAL SCENARIOS
###############################################################################
##
## Three transmission settings:
##
##     Low     ABR = 2942
##     Medium  ABR = 5350
##     High    ABR = 27000
##
## For:
##
##     ivermectin / moxidectin
##     annual / biannual
##     VR / GR-only
##
###############################################################################


ABR_map <- c(
  Low = 2942,
  Med = 5350,
  Hig = 27000
)

original_manifest <- expand.grid(
  
  transmission =
    names(ABR_map),
  
  frequency =
    c(
      "Biannual",
      "Annual"
    ),
  
  drug =
    c(
      "Ivermectin",
      "Moxidectin"
    ),
  
  model =
    c(
      "VR",
      "GR-only"
    ),
  
  stringsAsFactors = FALSE
)


original_manifest$ABR <-
  unname(
    ABR_map[
      original_manifest$transmission
    ]
  )


original_manifest$filename <-
  mapply(
    
    function(
    transmission,
    frequency,
    drug,
    model) {
      
      drug_code <- ifelse(
        drug == "Ivermectin",
        "MDAi",
        "MDAm"
      )
      
      freq_code <- ifelse(
        frequency == "Annual",
        "A",
        "B"
      )
      
      model_code <- ifelse(
        model == "GR-only",
        "_GR",
        ""
      )
      
      file.path(
        output_dir,
        paste0(
          drug_code,
          "_",
          transmission,
          "_",
          freq_code,
          model_code,
          ".Rdata"
        )
      )
    },
    
    original_manifest$transmission,
    original_manifest$frequency,
    original_manifest$drug,
    original_manifest$model,
    
    USE.NAMES = FALSE
  )


original_manifest$Scenario_group <-
  "Original"

original_manifest$Calibration <-
  "Primary"

original_manifest$Model <-
  original_manifest$model

original_manifest$Drug <-
  original_manifest$drug

original_manifest$Frequency <-
  original_manifest$frequency

###############################################################################
## REVISED SENSITIVITY SCENARIOS
###############################################################################
##
## All use:
##     ABR = 27000 (~70% baseline prevalence)
##     ivermectin
##
## For:
##     annual / biannual
##     VR / GR-only
##
## Calibration analyses:
##     Primary
##     Moderate SOR increase
##     Weak SOR increase
##     No offspring-phenotype selection
##     Wider prevalence
##
###############################################################################

sensitivity_manifest <- expand.grid(
  
  Calibration = c(
    "Primary",
    "Moderate",
    "Weak",
    "No selection",
    "Wider prevalence"
  ),
  
  Model = c(
    "VR",
    "GR-only"
  ),
  
  Frequency = c(
    "Annual",
    "Biannual"
  ),
  
  stringsAsFactors = FALSE
)

sensitivity_manifest$ABR <-
  27000

sensitivity_manifest$Drug <-
  "Ivermectin"

sensitivity_manifest$Scenario_group <-
  "Sensitivity"

###############################################################################
## Map calibration names to filenames
###############################################################################

calibration_suffix <- c(
  
  "Primary" =
    "",
  
  "Moderate" =
    "_Moderate",
  
  "Weak" =
    "_Weak",
  
  "No selection" =
    "_NoSelection",
  
  "Wider prevalence" =
    "_WiderPrev"
)

sensitivity_manifest$filename <-
  mapply(
    
    function(
    calibration,
    model,
    frequency) {
      
      freq_code <- ifelse(
        frequency == "Annual",
        "A",
        "B"
      )
      
      model_code <- ifelse(
        model == "GR-only",
        "_GR",
        ""
      )
      
      file.path(
        output_dir,
        paste0(
          "MDAi_Hig_",
          freq_code,
          model_code,
          calibration_suffix[[calibration]],
          ".Rdata"
        )
      )
    },
    
    sensitivity_manifest$Calibration,
    sensitivity_manifest$Model,
    sensitivity_manifest$Frequency,
    
    USE.NAMES = FALSE
  )


###############################################################################
## Combine scenario manifests
###############################################################################

scenario_manifest <- bind_rows(
  
  original_manifest %>%
    
    transmute(
      Scenario_group,
      Calibration,
      Model,
      Drug,
      Frequency,
      ABR,
      filename
    ),
  
  sensitivity_manifest %>%
    
    transmute(
      Scenario_group,
      Calibration,
      Model,
      Drug,
      Frequency,
      ABR,
      filename
    )
)


###############################################################################
## Remove duplicate primary scenarios
##
## The primary high-prevalence ivermectin scenarios occur in both the
## original and sensitivity manifests.
###############################################################################

scenario_manifest <-
  scenario_manifest %>%
  
  distinct(
    filename,
    .keep_all = TRUE
  )


###############################################################################
## Check which files are available
###############################################################################

scenario_manifest$exists <-
  file.exists(
    scenario_manifest$filename
  )

message(
  "\nScenario files found: ",
  sum(scenario_manifest$exists),
  " of ",
  nrow(scenario_manifest),
  "\n"
)


if (
  any(
    !scenario_manifest$exists
  )
) {
  
  message(
    "Missing files:"
  )
  
  print(
    
    scenario_manifest[
      !scenario_manifest$exists,
      
      c(
        "Calibration",
        "Model",
        "Drug",
        "Frequency",
        "filename"
      )
    ],
    
    row.names = FALSE
  )
}

###############################################################################
## Process all available scenario files
###############################################################################

processed_list <- vector(
  "list",
  nrow(scenario_manifest)
)

for (
  i in seq_len(
    nrow(scenario_manifest)
  )
) {
  
  x <-
    scenario_manifest[i, ]
  
  
  processed_list[[i]] <-
    
    process_scenario_file(
      
      filename =
        x$filename,
      
      scenario_group =
        x$Scenario_group,
      
      calibration =
        x$Calibration,
      
      model =
        x$Model,
      
      drug =
        x$Drug,
      
      frequency =
        x$Frequency,
      
      ABR =
        x$ABR
    )
}

###############################################################################
## Remove scenarios that were not available
###############################################################################

processed_list <-
  Filter(
    Negate(is.null),
    processed_list
  )

if (
  length(processed_list) == 0
) {
  
  stop(
    "No scenario files were successfully processed."
  )
}


###############################################################################
## Combine into one data frame
###############################################################################

processed_all <-
  bind_rows(
    processed_list
  )

###############################################################################
## Add prevalence percentages
##
## Keep the original proportions as well so downstream analyses can use
## either representation without repeated conversions.
###############################################################################

processed_all$Final_Prevalence_percent <-
  processed_all$Final_Prevalence *
  100

processed_all$Final_Prevalence_GR_percent <-
  processed_all$Final_Prevalence_GR *
  100

processed_all$Final_Prevalence_SOR_percent <-
  processed_all$Final_Prevalence_SOR *
  100

###############################################################################
## Set factor ordering
###############################################################################

processed_all$Calibration <-
  factor(
    processed_all$Calibration,
    levels = c(
      "Primary",
      "Moderate",
      "Weak",
      "No selection",
      "Wider prevalence"
    )
  )

processed_all$Model <-
  factor(
    processed_all$Model,
    levels = c(
      "VR",
      "GR-only"
    )
  )

processed_all$Drug <-
  factor(
    processed_all$Drug,
    levels = c(
      "Ivermectin",
      "Moxidectin"
    )
  )

processed_all$Treatment_frequency <-
  factor(
    processed_all$Treatment_frequency,
    levels = c(
      "Biannual",
      "Annual"
    )
  )

###############################################################################
## Save processed results
###############################################################################

save(
  processed_all,
  scenario_manifest,
  file =
    "processed_all_scenarios.RData"
)

write.csv(
  processed_all,
  file =
    "processed_all_scenarios.csv",
  row.names = FALSE
)

###############################################################################
## Summary
###############################################################################

message(
  "\nFinished processing scenario outputs."
)

message(
  "Scenario files processed: ",
  length(processed_list)
)

message(
  "Total trajectories processed: ",
  nrow(processed_all)
)

message(
  "\nOutputs:"
)

message(
  "  processed_all_scenarios.RData"
)

message(
  "  processed_all_scenarios.csv"
)